          "ante domum quondamque suīs errāvit in agrīs!",
          "ā! quotiēns per saxa cānum lātrātibus ācta est",
          "vēnātrīxque metū venantum territa fugit!",
          "saepe ferīs latuit vīsīs, oblīta quid esset,",
