        "latinTitle": "VERSŪS 572–691",
        "title": "Verses 572–691",
        "hideHead": false,
        "paragraphs": [
          "Ecce cruentātī redeunt et, Bacchus ubi esset,",
          "quaerentī dominō Bacchum vīdisse negārunt;",
          "'hunc' dīxēre 'tamen comitem famulumque sacrōrum",
          "cēpimus' et trādunt manibus post terga ligātis",
          "sacra deī quendam Tyrrhēnā gente secūtum.",
          "adspicit hunc Penthēus oculīs, quōs īra tremendōs",
          "fēcerat, et quamquam poenae vix tempora differt,",
          "'ō peritūre tuaque aliīs documenta datūre",
          "morte,' ait, 'ēde tuum nōmen nōmenque parentum",
          "et patriam, morisque novī cūr sacra frequentēs!'",
          "ille metū vacuus 'nōmen mihi' dīxit 'Acoetēs,",
          "patria Maeonia est, humilī dē plēbe parentēs.",
          "nōn mihi quae dūrī colerent pater arva iuvencī,",
          "lānigerōsve gregēs, nōn ūlla armenta relīquit;",
          "pauper et ipse fuit līnōque solēbat et hāmīs",
          "dēcipere et calamō salientīs dūcere piscēs.",
          "ars illī suā cēnsus erat; cum trāderet artem,",
          "\"accipe, quās habeō, studiī successor et hērēs,\"",
          "dīxit \"opēs,\" moriēnsque mihi nihil ille relīquit",
          "praeter aquās: ūnum hoc possum adpellāre paternum.",
          "mox ego, nē scopulīs haerērem semper in īsdem,",
          "addidicī regimen dextrā moderante carīnae",
          "flectere et Ōleniae sīdus pluviāle capellae",
          "Tāygetēnque Hyadasque oculīs Arctōnque notāvī",
          "ventōrumque domōs et portūs puppibus aptōs.",
          "forte petēns Dēlum Chīae tellūris ad ōrās",
          "adplicor et dextrīs addūcor lītora rēmīs",
          "dōque levis saltūs ūdaeque inmittor harēnae:",
          "nox ibi cōnsūmpta est; aurōra rubēscere prīmō",
          "coeperat: exsurgō laticēsque īnferre recentīs",
          "admoneō mōnstrōque viam, quae dūcat ad undās;",
          "ipse quid aura mihi tumulō prōmittat ab altō",
          "prōspiciō comitēsque vocō repetōque carīnam.",
          "\"adsumus ēn\" inquit sociōrum prīmus Opheltēs,",
          "utque putat, praedam dēsertō nactus in agrō,",
          "virginea puerum dūcit per lītora fōrma.",
          "ille merō somnōque gravis titubāre vidētur",
          "vixque sequī; spectō cultum faciemque gradumque:",
          "nīl ibi, quod crēdī posset mortāle, vidēbam.",
          "et sēnsī et dīxī sociīs: \"quod nūmen in istō",
          "corpore sit, dubitō; sed corpore nūmen in istō est!",
          "quisquis es, ō faveās nostrīsque labōribus adsīs;",
          "hīs quoque dēs veniam!\" \"prō nōbīs mitte precārī!\"",
          "Dictys ait, quō nōn alius cōnscendere summās",
          "ōcior antemnās prēnsōque rudente relābī.",
          "hoc Libys, hoc flāvus, prōrae tūtēla, Melanthus,",
          "hoc probat Alcimedōn et, quī requiemque modumque",
          "vōce dabat rēmīs, animōrum hortātor, Epopeus,",
          "hoc omnēs aliī: praedae tam caeca cupīdō est.",
          "\"nōn tamen hanc sacrō violārī pondere pīnum",
          "perpetiar\" dīxī: \"pars hīc mihi maxima iūris\"",
          "inque aditū obsistō: furit audācissimus omnī",
          "dē numerō Lycabās, quī Tuscā pulsus ab urbe",
          "exilium dīra poenam prō caede luēbat;",
          "is mihi, dum restō, iuvenālī guttura pugnō",
          "rūpit et excussum mīsisset in aequora, sī nōn",
          "haesissem, quamvīs āmēns, in fūne retentūs.",
          "inpia turba probat factum; tum dēnique Bacchus",
          "(Bacchus enim fuerat), velutī clāmōre solūtus",
          "sit sopor āque merō redeant in pectora sēnsūs,",
          "\"quid facitis? quis clāmor?\" ait \"qua, dīcite, nautae,",
          "hūc ope pervēnī? quō mē dēferre parātis?\"",
          "\"pōne metum\" Prōreus, \"et quōs contingere portūs",
          "ēde vēlīs!\" dīxit; \"terra sistere petīta.\"",
          "\"Naxon\" ait Liber \"cursūs advertite vestrōs!",
          "illa mihi domus est, vōbīs erit hospita tellūs.\"",
          "per mare fallācēs perque omnia nūmina iūrant",
          "sīc fore mēque iubent pictae dare vēla carīnae.",
          "dexterā Naxos erat: dextra mihi lintea dantī",
          "\"quid facis, ō dēmēns? quis tē furor,\" inquit \"Acoete,\"",
          "prō sē quisque, \"tenet? laevam pete!\" maxima nūtū",
          "pars mihi significat, pars quid velit ōre susurrō.",
          "obstipuī \"capiat\" que \"aliquis moderāmina!\" dīxī",
          "mēque ministeriō scelerisque artisque remōvī.",
          "increpor ā cūnctīs, tōtumque inmurmurat agmen;",
          "ē quibus Aethalīōn \"tē scīlicet omnis in ūnō",
          "nostra salūs posita est!\" ait et subit ipse meumque",
          "explet opus Naxōque petit dīversā relicta.",
          "tum deus inlūdēns, tamquam modo dēnique fraudem",
          "sēnserit, ē puppī pontum prōspectat aduncā",
          "et flentī similis \"nōn haec mihi lītora, nautae,",
          "prōmīsistis\" ait, \"nōn haec mihi terra rogāta est!",
          "quō meruī poenam factō? quae glōria vestra est,",
          "sī puerum iuvenēs, sī multī fallitis ūnum?\"",
          "iamdūdum flēbam: lacrimās manus inpia nostrās",
          "rīdet et inpellit properantibus aequora rēmīs.",
          "per tibi nunc ipsum (nec enim praesentior illō",
          "est deus) adiūrō, tam mē tibi vēra referre",
          "quam vērī maiōra fide: stetit aequore puppis",
          "haud aliter, quam sī siccam nāvāle tenēret.",
          "illī admīrantēs rēmōrum in verbere perstant",
          "vēlaque dēdūcunt gemināque ope currere temptant:",
          "inpediunt hederae rēmōs nexūque recurvō",
          "serpunt et gravidīs distinguunt vēla corymbīs.",
          "ipse racēmiferīs frontem circumdatus ūvīs",
          "pampineīs agitat vēlātam frondibus hastam;",
          "quem circā tigrēs simulācraque inānia lyncum",
          "pictārumque iacent fera corpora panthērārum.",
          "exsiluēre virī, sīve hoc īnsānia fēcit",
          "sīve timor, prīmusque Medōn nigrēscere tōtō",
          "corpore et expressō spīnae curvāmine flectī",
          "incipit. huic Lycabās \"in quae mīrācula\" dīxit",
          "\"verterīs?\" et lātī rictus et panda loquentī",
          "nāris erat, squāmamque cutis dūrāta trahēbat.",
          "at Libys obstantis dum vult obvertere rēmōs,",
          "in spatium resilīre manūs breve vīdit et illās",
          "iam nōn esse manūs, iam pinnās posse vocārī.",
          "alter ad intortōs cupiēns dare bracchia fūnēs",
          "bracchia nōn habuit truncōque repandus in undās",
          "corpore dēsiluit: falcāta novissima cauda est,",
          "quālia dīviduae sinuantur cornua lūnae.",
          "undique dant saltūs multaque adspergine rōrant",
          "ēmerguntque iterum redeuntque sub aequora rūrsus",
          "inque chorī lūdunt speciem lascīvaque iactant",
          "corpora et acceptum patulīs mare nāribus efflant.",
          "dē modō vīgintī (tot enim ratīs illā ferēbat)",
          "restābam sōlus: pavidum gelidumque trementī",
          "corpore vixque meum firmat deus \"excute\" dīcēns",
          "\"cordē metum Dīamque tenē!\" dēlātus in illam",
          "accessī sacrīs Bacchēaque sacra frequentō.'"
        ],
