        "id": "metamorphoses-liber-iii-r7",
        "latinTitle": "VERSŪS 692–733",
        "title": "Verses 692–733",
        "hideHead": false,
        "paragraphs": [
          "'Praebuimus longīs' Penthēus 'ambāgibus aurēs,'",
          "inquit 'ut īrā mōrā vīrēs absūmere posset.",
          "praecipitem, famulī, rapite hunc cruciātaque dīrīs",
          "corpora tormentīs Stygiae dēmittite noctī!'",
          "prōtinus abstractus solidīs Tyrrhēnus Acoetēs",
          "clauditur in tēctīs; et dum crūdēlia iussae",
          "īnstrūmenta necīs ferrumque ignēsque parantur,",
          "sponte suā patuisse forēs lāpsāsque lacertīs",
          "sponte suā fāmā est nūllō solvente catēnās.",
          "Perstat Echīonidēs, nec iam iubet īre, sed ipse",
          "vādit, ubi ēlēctus facienda ad sacra Cithaerōn",
          "cantibus et clārā bacchantum vōce sonābat.",
          "ut fremit ācer equus, cum bellicus aere canōrō",
          "signa dedit tubicen pugnaeque adsūmit amōrem,",
          "Penthēa sīc ictus longīs ululātibus aether",
          "mōvit, et audītō clāmōre recanduit īra.",
          "Monte ferē mediō est, cingentibus ultima silvīs,",
          "pūrus ab arboribus, spectābilis undique, campus:",
          "hīc oculīs illum cernentem sacra profānīs",
          "prīma videt, prīma est īnsānō concitā cursū,",
          "prīmā suum missō violāvit Penthēa thyrsō",
          "māter et 'ō geminae' clāmāvit 'adeste sorōrēs!",
          "ille aper, in nostrīs errat quī maximus agrīs,",
          "ille mihi feriendus aper.' ruit omnis in ūnum",
          "turbā furēns; cūnctae coeunt trepidumque sequuntur,",
          "iam trepidum, iam verba minus violenta loquentem,",
          "iam sē damnantem, iam sē peccāsse fatentem.",
          "saucius ille tamen 'fer opem, mātertera' dīxit",
          "'Autonoē! moveant animōs Actaeonis umbrae!'",
          "illa, quis Actaeōn, nescit dextramque precantī",
          "abstulit, Īnōō lacerāta est altera raptū.",
          "nōn habet īnfēlīx quae mātrī bracchia tendat,",
          "trunca sed ostendēns dēreptīs vulnera membrīs",
          "'adspice, māter!' ait. vīsis ululāvit Agāuē",
          "collaque iactāvit mōvitque per āera crīnem",
          "āvulsumque caput digitīs conplexa cruentīs",
          "clāmat: 'iō comitēs, opus hoc victōria nostra est!'",
          "nōn citius frondēs autumnī frīgore tāctās",
          "iamque male haerentēs altā rapit arbore ventus,",
          "quam sunt membra virī manibus dīrepta nefandīs.",
          "tālibus exemplīs monitae nova sacra frequentant",
          "tūraque dant sānctāsque colunt Ismēnidēs ārās."
        ],
