          "discutit ōra ferōx; tum dēnique concita māter,",
          "seu dolor hoc fēcit seu sparsī causa venēnī,",
          "exululat passīsque fugit male sāna capillīs",
          "tēque ferēns parvum nūdīs, Melicerta, lacertīs",
          "'euhoe Bacche' sonat: Bacchī sub nōmine Iūnō",
          "rīsit et 'hōs ūsus praestet tibi' dīxit 'alumnus!'",
          "inminet aequoribus scopulus: pars īma cavātur",
          "flūctibus et tēctās dēfendit ab imbribus undās,",
          "summa riget frontemque in apertum porrigit aequor;",
          "occupat hunc (vīrēs īnsānia fēcerat) Īnō",
          "sēque super pontum nūllō tardāta timōre",
          "mittit onusque suum; percussa recanduit unda.",
          "At Venus, inmeritae neptis miserāta labōrēs,",
          "sīc patruō blandīta suō est 'ō nūmen aquārum,",
          "proxima cui caelō cessit, Neptūne, potestās,",
          "magna quidem poscō, sed tū miserēre meōrum,",
          "iactārī quōs cernis in Ioniō inmēnsō,",
          "et dīs adde tuīs. aliquā et mihi grātia pontō est,",
          "sī tamen in mediō quondam concrēta profundō",
          "spūmā fuī Grāiumque manet mihi nōmen ab illā.'",
          "adnuit ōrantī Neptūnus et abstulit illīs,",
          "quod mortāle fuit, maiestātemque verendam",
          "inposuit nōmenque simul faciemque novāvit",
          "Leucothoēque deum cum mātre Palaemonā dīxit."
