          "dēplānxēre domum scissae cum veste capillōs,",
          "utque parum iūstae nimiumque in paelice saevae",
          "invidiam fēcēre deae. convīcia Iūnō",
          "nōn tulit et 'faciam vōs ipsās maxima' dīxit",
          "'saevitiae monimenta meae'; rēs dicta secūta est.",
          "nam quae praecipuē fuerat pia, 'persequar' inquit",
          "'in frētā rēgīnam' saltumque datūrā movērī",
          "haud usquam potuit scopulōque adfixa cohaesit;",
          "altera, dum solitō temptat plangōre ferīre",
          "pectora, temptātōs sēnsit riguisse lacertōs;",
          "illa, manus ut forte tetenderat in maris undās;",
          "saxea facta manūs in eāsdem porrigit undās;",
          "huius, ut arreptum laniābat vertice crīnem,",
          "dūrātōs subitō digitōs in crīne vidērēs:",
          "quō quaeque in gestū dēprēnsa est, haesit in illō.",
          "pars volucrēs factae, quae nunc quoque gurgite in illō",
          "aequora dēstringunt summīs Ismēnidēs ālīs.",
