          "aequoris esse deōs; lūctū seriēque malōrum",
          "vīctūs et ostentīs, quae plūrima vīderat, exit",
          "conditor urbe suā, tamquam fortūna locōrum,",
          "nōn suā sē premeret, longīsque errōribus āctus",
          "contigit Illyricōs profuga cum coniuge fīnēs.",
