          "prōiectō tua facta loquar: sī cōpia dētur,",
          "in populōs veniam; sī silvīs clausa tenēbor,",
          "inplēbō silvās et cōnscia saxa movēbō;",
          "audiet haec aether et sī deus ūllus in illō est!'"
