      {
        "id": "metamorphoses-liber-vii-r8",
        "latinTitle": "VERSŪS 796–865",
        "title": "Verses 796–865",
        "hideHead": false,
        "paragraphs": [
          "'Gaudia prīncipium nostrī sunt, Phōce, dolōris:",
          "illa prius referam. iuvat ō meminisse beātī",
          "temporis, Aeacidē, quō prīmōs rīte per annōs",
          "coniuge eram fēlīx, fēlīx erat illā marītō.",
          "mūtua cūra duōs et amor sociālis habēbat,",
          "nec Iovis illa meō thalamōs praeferret amōrī,",
          "nec mē quae caperet, nōn sī Venus ipsa venīret,",
          "ūlla erat; aequālēs ūrēbant pectora flammae.",
          "sōlē ferē radiīs feriente cacūmina prīmīs",
          "vēnātum in silvās iuvenāliter īre solēbam",
          "nec mēcum famulī nec equī nec nāribus ācrēs",
          "īre canēs nec līna sequī nōdōsa solēbant:",
          "tūtus eram iaculō; sed cum satiāta ferīnae",
          "dexterā caedis erat, repetēbam frīgus et umbrās",
          "et quae dē gelidīs exībat vallibus aura:",
          "aura petēbātur mediō mihi lēnis in aestū,",
          "auram exspectābam, requiēs erat illa labōrī.",
          "\"aura\" (recordor enim), \"veniās\" cantāre solēbam,",
          "\"mēque iuvēs intrēsque sinūs, grātissima, nostrōs,",
          "utque facis, relevāre velīs, quibus ūrimur, aestus!\"",
          "forsitan addiderim (sīc mē mea fāta trahēbant),",
          "blanditiās plūrēs et \"tū mihi magna voluptās\"",
          "dīcere sim solitus, \"tū mē reficisque fovēsque,",
          "tū facis, ut silvās, ut amem loca sōla: meōque",
          "spīritus iste tuus semper captātur ab ōre.\"",
          "vōcibus ambiguīs dēceptam praebuit aurem",
          "nesciō quis nōmenque aurae tam saepe vocātum",
          "esse putat nymphae: nympham mihi crēdit amārī.",
          "crīminis extemplō fictī temerārius index",
          "Procrin adit linguaque refert audīta susurrā.",
          "crēdula rēs amor est: subitō conlāpsā dolōre,",
          "ut mihi nārrātur, cecidit; longōque refecta",
          "tempore sē miseram, sē fātī dīxit inīquī",
          "dēque fide questa est et crīmine concitā vānō,",
          "quod nihil est, metuit, metuit sine corpore nōmen",
          "et dolet īnfēlīx velutī dē paelice vērā.",
          "saepe tamen dubitat spēratque miserrima fallī",
          "indiciīque fidem negat et, nisi vīderit ipsa,",
          "damnātūra suī nōn est dēlicta marītī.",
          "postera dēpulerant Aurōrae lūmina noctem:",
          "ēgredior silvamque petō victorque per herbās",
          "\"aura, venī\" dīxī \"nostrōque medēre labōrī!\"",
          "et subitō gemitus inter mea verba vidēbar",
          "nesciō quōs audīsse; \"venī\" tamen \"optima!\" dīcēns",
          "fronde levem rūrsus strepitum faciente cadūca",
          "sum ratus esse feram tēlumque volātile mīsī:",
          "Procris erat mediōque tenēns in pectore vulnus",
          "\"eī mihi\" conclāmat! vōx est ubi cognita fīdae",
          "coniugis, ad vōcem praeceps āmēnsque cucurrī.",
          "sēmianimem et sparsās foedantem sanguine vestēs",
          "et sua (mē miserum!) dē vulnere dōna trahentem",
          "inveniō corpusque meō mihi cārius ulnīs",
          "mollibus attollō scissāque ā pectore veste",
          "vulnera saeva ligō cōnorque inhibēre cruōrem",
          "neu mē morte suā scelerātum dēserat, ōrō.",
          "vīribus illa cārēns et iam moribunda coēgit",
          "haec sē pauca loquī: \"per nostrī foedera lectī",
          "perque deōs supplex ōrō superōsque meōsque,",
          "per sī quid meruī dē tē bene perque manentem",
          "nunc quoque, cum pereō, causam mihi mortis amōrem,",
          "nē thalamīs Auram patiāre innūbere nostrīs!\"",
          "dīxit, et errōrem tum dēnique nōminis esse",
          "et sēnsī et docuī. sed quid docuisse iuvābat?",
          "lābitur, et parvae fugiunt cum sanguine vīrēs,",
          "dumque aliquid spectāre potest, mē spectat et in mē",
          "īnfēlīcem animam nostrōque exhālat in ōre;",
          "sed vultū meliōre morī sēcūrā vidētur.'",
          "Flentibus haec lacrimāns hērōs memorābat, et ecce",
          "Aeacus ingreditur duplicī cum prōle novōque",
          "mīlite; quem Cephalus cum fortibus accipit armīs."
        ],
        "notes": []
      }
