          "mē tamen acceptā poterat dēpōnere bellum",
          "obside: mē comitem, mē pācis pignus habēret.",
          "sī quae tē peperit, tālis, pulcherrimē rēgum,",
          "quālis es ipse, fuit, meritō deus ārsit in illā.",
          "ō ego ter fēlīx, sī pennīs lāpsa per aurās",
          "Cnosiācī possem castrīs īnsistere rēgis",
          "fassaque mē flammāsque meās, quā dōte, rogārem,",
          "vellet ēmī, tantum patriās nē posceret arcēs!",
          "nam pereant potius spērāta cubīlia, quam sim",
          "prōditiōne potēns!—quamvīs saepe ūtile vincī",
          "victōris placidī fēcit clēmentiā multīs.",
          "iūsta gerit certē prō nātō bella perēmptō:",
          "et causaque valet causamque tuentibus armīs.",
          "at, putō, vincēmur; quī sī manet exitus urbem,",
          "cūr suus haec illī reseret mea moenia Māvors",
          "et nōn noster amor? melius sine caede morāque",
          "inpēnsāque suī poterit superāre cruōris.",
          "nōn metuam certē, nē quis tua pectora, Mīnōs,",
          "vulneret inprūdēns: quis enim tam dūrus, ut in tē",
          "dērigēre inmītem nōn īnscius audeat hastam?",
          "coepta placent, et stat sententia trādere mēcum",
          "dōtālem patriam fīnemque inpōnere bellō;",
          "vērum velle parum est! aditus cūstōdia servat,",
          "claustraque portārum genitor tenet: hunc ego sōlum",
