          "et plausit pennīs testātaque gaudia cantū est,",
          "ūnica tunc volucris nec vīsa priōribus annīs,",
          "factaque nūper avīs longum tibi, Daedale, crīmen.",
          "namque huic trādiderat, fātōrum ignāra, docendam",
          "prōgeniem germānā suam, nātālibus āctīs",
          "bis puerum senis, animī ad praecepta capācīs;",
          "ille etiam mediō spīnās in pisce notātās",
          "trāxit in exemplum ferrōque incīdit acūtō",
          "perpetuōs dentēs et serrae repperit ūsum;",
          "prīmus et ex ūnō duo ferreā bracchia nōdō",
          "vīnxit, ut aequālī spatiō distantibus illīs",
          "altera pars stāret, pars altera dūceret orbem.",
