          "praecipitem mīsit, lāpsum mentītus; at illum,",
          "quae favet ingeniīs, excēpit Pallās avemque",
          "reddidit et mediō vēlāvit in aere pennīs,",
          "sed vigor ingeniī quondam vēlōcis in ālās",
          "inque pedēs abiit; nōmen, quod et ante, remānsit.",
          "nōn tamen haec altē volucris sua corpora tollit,",
          "nec facit in rāmīs altōque cacūmine nīdōs:",
          "propter humum volitat pōnitque in saepibus ōva",
          "antīquīque memor metuit sublīmia cāsūs.",
          "Iamque fatīgātum tellūs Aetnaeā tenēbat",
          "Daedalōn, et sūmptīs prō supplice Cōcalus armīs",
          "mītīs habēbātur; iam lāmentābile Athēnae",
          "pendēre dēsierant Thēsēā laude tribūtum:",
