          "tam piā semper\" ait. pietātis nōmine dictō",
          "dēmīsit vultūs sceleris sibi cōnscia virgō.",
          "'Noctis erat medium, cūrāsque et corpora somnus",
          "solverat; at virgō Cinyrēia pervigil ignī",
          "carpitur indomitō furiōsaque vōta retractat",
          "et modo dēspērat, modo vult temptāre, pudetque",
          "et cupit, et, quid agat, nōn invēnit, utque secūrī",
          "saucia trabs ingēns, ubi plāga novissima restat,",
