          "nec modus et requiēs, nisi mors, reperītur amōris.",
          "mors placet. ērigitur laqueōque innectere faucēs",
          "dēstinat et zōnā summō dē poste revīncta",
          "\"care, valē, Cinyra, causamque intellege mortis!\"",
          "dīxit et aptābat pallentī vincula collō.",
          "'Murmura verbōrum fīdās nūtrīcis ad aurēs",
          "pervēnisse ferunt līmen servantis alumnae.",
          "surgit ānus reseratque forēs mortīsque parātae",
          "īnstrūmenta vidēns spatiō conclāmat eōdem",
          "sēque ferit scinditque sinus ēreptaque collō",
          "vincula dīlaniat; tum dēnique flēre vacāvit,",
          "tum dare conplexus laqueīque requīrere causam.",
          "mūta silet virgō terramque inmōtā tuētur",
          "et dēprēnsa dolet tardae cōnāmina mortis.",
          "īnstat anūs cānōsque suōs et inānia nūdāns",
          "ūbera per cūnās alimentaque prīma precātur,",
          "ut sibi committat, quicquid dolet. illa rogantem",
          "āversāta gemit; certa est exquīrere nūtrīx",
          "nec sōlam spondēre fidem. \"dīc\" inquit \"opemque",
          "mē sine ferre tibi: nōn est mea pigra senectūs.",
          "seu furor est, habeō, quae carmine sānet et herbīs;",
          "sīve aliquis nocuit, magicō lūstrābere rītū;",
          "īra deum sīve est, sacrīs plācābilis īrā.",
          "quid rear ulterius? certē fortūna domusque",
          "sospes et in cursū est: vīvunt genetrīxque paterque.\"",
          "Myrrha patre audītō suspīria dūxit ab īmō",
          "pectore; nec nūtrīx etiamnum concipit ūllum",
          "mente nefās aliquemque tamen praesentit amōrem;",
          "prōpositīque tenāx, quodcumque est, ōrat, ut ipsī",
