          "atque ita conplēctēns īnfirmīs membra lacertīs",
          "\"sēnsimus,\" inquit \"amās! et in hōc mea (pōne timōrem)",
          "sēdulitās erit apta tibi, nec sentiet umquam",
          "hoc pater.\" exiluit gremiō furibunda torumque",
          "ōre premēns \"discēde, precor, miserōque pudōrī",
          "parce!\" ait; īnstantī \"discēde, aut dēsine\" dīxit",
          "\"quaerere, quid doleam! scelus est, quod scīre labōrās.\"",
          "horret anus tremulāsque manūs annīsque metūque",
          "tendit et ante pedēs supplex prōcumbit alumnae",
          "et modo blandītur, modo, sī nōn cōnscia fīat,",
          "terret et indicium laqueī coeptaeque minātur",
          "mortis et officium commissō spondet amōrī.",
          "extulit illa caput lacrimīsque inplēvit obortīs",
          "pectora nūtrīcis cōnātaque saepe fatērī",
          "saepe tenet vōcem pudibundaque vestibus ōra",
          "tēxit et \"ō\" dīxit \"fēlīcem coniuge mātrem!\"",
          "hāctenus, et gemuit. gelidus nūtrīcis in artūs",
          "ossaque (sēnsit enim) penetrat tremor, albaque tōtō",
          "vertice cānitiēs rigidīs stetit hirta capillīs,",
          "multaque, ut excuteret dīrōs, sī posset, amōrēs,",
          "addidit. at virgō scit sē nōn falsā monērī;",
          "certa mōrī tamen est, sī nōn potiātur amōre.",
          "\"vīve,\" ait haec, \"potiere tuō\"—et, nōn ausa \"parente\"",
          "dīcere, conticuit prōmissaque nūmine firmat."
