          "et color et sanguis, animusque relinquit euntem.",
          "quoque suō propior scelerī est, magis horret, et ausī",
          "paenitet, et vellet nōn cognitā posse revertī.",
          "cūnctantem longaevā manū dēdūcit et altō",
