          "forsitan aetātis quoque nōmine \"fīlia\" dīxit,",
          "dīxit et illa \"pater,\" scelerī nē nōmina dēsint.",
          "'Plēna patris thalamīs excēdit et inpia dīrō",
          "sēmina fert uterō conceptaque crīmina portat.",
          "postera nox facinus geminat, nec fīnis in illā est,",
