          "et scelus et nātam verbīsque dolōre retentīs",
          "pendentī nitidum vāgīnā dēripit ēnsem;",
          "Myrrha fugit: tenebrīsque et caecae mūnere noctis",
          "intercepta necī est lātōsque vagāta per agrōs",
          "palmiferōs Arabās Panchaeaque rūra relinquit",
          "perque novem errāvit redeuntīs cornua lūnae,",
          "cum tandem terra requiēvit fessa Sabaea;",
