          "est honor et lacrimīs, stillātāque cortice murrā",
          "nōmen erīle tenet nūllōque tacēbitur aevō.",
          "'At male conceptus sub rōbore crēverat īnfāns",
          "quaerēbatque viam, quā sē genetrīce relicta",
          "exsereret; mediā gravidus tumet arbore venter.",
          "tendit onus mātrem; neque habent sua verba dolōrēs,",
