          "reddit onus, vāgitque puer; quem mollibus herbīs",
          "naidēs inpositum lacrimīs ūnxēre parentīs.",
          "laudāret faciem Līvor quoque; quālia namque",
          "corpora nūdōrum tabulā pinguntur Amōrum,",
