          "inclīnāvit aquās ad avārae lītora Troiae",
          "inque fretī fōrmam terrās conplēvit opēsque",
          "abstulit agricolīs et flūctibus obruit agrōs.",
          "poena neque haec satis est: rēgis quoque fīlia mōnstrō",
          "poscitur aequoreō, quam dūra ad saxa revīnctam",
          "vindicat Alcīdēs prōmissaque mūnera dictōs",
