          "quī vocat Aurōram caelōque novissimus exit,",
          "culta mihi pāx est, pācis mihi cūra tenendae",
          "coniugiīque fuit, frātrī fera bella placēbant:",
          "illīus virtūs rēgēs gentēsque subēgit,",
          "quae nunc Thisbaeās agitat mūtāta columbās.",
          "nāta erat huic Chionē, quae dōtātissima fōrma",
          "mīlle procōs habuit, bis septem nūbilīs annīs.",
          "forte revertentēs Phoebus Maiaque creātus,",
          "ille suīs Delphīs, hic vertice Cyllenaēō,",
          "vīdēre hanc pariter, pariter trāxēre colōrem.",
          "spem vēnerīs differt in tempora noctis Apollō;",
          "nōn fert ille morās virgāque movente sopōrem",
          "virginis os tangit: tāctū iacet illa potentī",
          "vimque deī patitur; nox caelum sparserat astrīs:",
          "Phoebus ānum simulat praereptaque gaudia sūmit.",
          "ut sua mātūrus conplēvit tempora venter,",
          "alipēdis dē stirpe deī versūta propāgō",
          "nāscitur Autolycus fūrtum ingeniōsus ad omne,",
          "candida dē nigrīs et dē candentibus ātra",
          "quī facere adsuerat, patriae nōn dēgener artis;",
          "nāscitur ē Phoebō (namque est ēnīxa gemellōs)",
          "carmine vōcālī clārus citharāque Philammōn.",
          "quid peperisse duōs et dīs placuisse duōbus",
          "et fortī genitōre et prōgenitōre nītentī",
          "esse satam prōdest? an obēst quoque glōria multīs?",
          "obfuit huic certē! quae sē praeferre Diānae",
          "sustinuit faciemque deae culpāvit, at illī",
          "īra ferōx mōta est \"factīs\" que \"placēbimus\" inquit.",
          "nec mora, curvāvit cornū nervōque sagittam",
          "inpulit et meritam trāiēcit harundine linguam.",
          "lingua tacet, nec vōx temptātaque verba sequuntur,",
