          "Quae dum Lūciferō genitus mīrācula nārrat",
          "dē cōnsorte suō, cursū festīnus anhēlō",
          "advolat armentī cūstōs Phōcēus Onētor",
          "et 'Peleu, Peleu! magnae tibi nūntius adsum",
          "clādis' ait. quodcumque ferat, iubet edere Peleus,",
          "pendet et ipse metū trepidī Trāchīnius ōris;",
          "ille refert 'fessōs ad lītora curva iuvencōs",
          "adpuleram, mediō cum Sōl altissimus orbe",
          "tantum respiceret, quantum superesse vidēret,",
          "parsque boum fulvīs genua inclīnārat harēnīs",
          "lātārumque iacēns campōs spectābat aquārum,",
          "pars gradibus tardīs illūc errābat et illūc;",
          "nant aliī celsōque exstant super aequora collō.",
          "templa marī subsunt nec marmore clārā neque aurō,",
          "sed trabibus dēnsīs lūcōque umbrōsā vetustō:",
          "Nēreidēs Nēreusque tenent (hōs nāvita pontī",
          "ēdidit esse deōs, dum rētia lītore siccat);",
          "iūncta palūs huic est dēnsīs obsessa salictīs,",
          "quam restāgnantis fēcit maris unda palūdem:",
          "inde fragōre gravī strepitāns loca proxima terret,",
          "bēlua vasta, lupus iuncīsque palūstribus exit,",
          "oblītus et spūmīs et sparsus sanguine rictūs",
          "fulmineōs, rubrā suffūsus lūmina flammā.",
          "quī quamquam saevit pariter rabiēque famēque,",
          "ācrior est rabiē: neque enim ieiūnia cūrat",
          "caede boum dīramque famem fīnīre, sed omne",
          "vulnerat armentum sternitque hostīliter omne.",
          "pars quoque dē nōbīs fūnestō saucia morsū,",
          "dum dēfēnsāmus, lētō est data; sanguine lītus",
          "undaque prīma rubet dēmūgītaeque palūdēs.",
          "sed mora damnōsa est, nec rēs dubitāre remittit:",
          "dum superest aliquid, cūnctī coeāmus et arma,",
          "arma capessāmus coniūnctaque tēla ferāmus!'",
          "dīxerat agrestis: nec Pelea damna movēbant,",
          "sed memor admissī Nēreida conligit orbam",
          "damna sua īnferiās exstīnctō mittere Phōcō.",
          "induere arma virōs violentaque sūmere tēla",
          "rēx iubet Oetaeus; cum quis simul ipse parābat",
          "īre, sed Alcyonē coniūnx excitā tumultū",
          "prōsilit et nōndum tōtōs ōrnāta capillōs",
          "disicit hōs ipsōs colloque īnfūsa marītī,",
          "mittat ut auxilium sine sē, verbīsque precātur",
          "et lacrimīs, animāsque duās ut servet in ūnā.",
          "Aeacidēs illī: 'pulchrōs, rēgīna, piōsque",
          "pōne metūs! plēnā est prōmissī grātiā vestrī.",
          "nōn placet arma mihi contrā nova mōnstra movērī;",
          "nūmen adōrandum pelagī est!' erat ardua turris,",
          "arce focus summa, fessīs nota grāta carīnīs:",
          "ascendunt illūc strātōsque in lītore taurōs",
          "cum gemitū adspiciunt vastātōremque cruentō",
          "ōre ferum, longōs īnfectum sanguine villōs.",
          "inde manus tendēns in apertī lītora pontī",
          "caeruleam Peleus Psamathēn, ut fīniat īram,",
          "ōrat, opemque ferat; nec vōcibus illa rogantīs",
          "flectitur Aeacidae, Thetis hanc prō coniuge supplex",
          "accēpit veniam. sed enim revocātus ab ācrī",
          "caede lupus perstat, dulcēdine sanguinis asper,",
          "dōnec inhaerentem lacerae cervīce iuvencae",
          "marmore mūtāvit: corpus praeterque colōrem",
          "omnia servāvit, lapidis color indicat illum",
          "iam nōn esse lupum, iam nōn dēbēre timērī.",
          "nec tamen hāc profugum cōnsistere Pelēā terrā",
          "fāta sinunt, Magnetās adit vagus exul et illīc",
          "sūmit ab Haemoniō pūrgāmina caedis Acastō.",
          "Intereā frātrisque suī frātremque secūtīs",
          "ānxia prōdigiīs turbātus pectora Ceyx,",
          "cōnsulat ut sacrās, hominum oblectāmina, sortēs,",
          "ad Clarium parat īre deum; nam templa profānus",
          "invia cum Phlegyīs faciēbat Delphica Phorbās.",
          "cōnsiliī tamen ante suī, fīdissima, certam",
          "tē facit, Alcyonē; cui prōtinus intima frīgus",
          "ossa recēpērunt, buxōque simillimus ōrā",
          "pallor obit, lacrimīsque genae maduēre profūsīs.",
