          "'quae mea culpa tuam,' dīxit 'cārissime, mentem",
          "vertit? ubi est quae cūra meī prior esse solēbat?",
          "iam potes Alcyonē sēcūrus abesse relicta?",
          "iam via longa placet? iam sum tibi cārior absēns?",
          "at, putō, per terrās iter est, tantumque dolēbō,",
          "nōn etiam metuam, cūraeque timōre carēbunt.",
          "aequora mē terrent et pontī trīstis imāgō:",
          "et lacerās nūper tabulās in lītore vīdī",
          "et saepe in tumulīs sine corpore nōmina legī.",
          "nēve tuum fallāx animum fīdūcia tangat,",
          "quod socer Hippotadēs tibi sit, quī carcere fortēs",
          "contineat ventōs, et, cum velit, aequora placet.",
          "cum semel ēmissī tenuērunt aequora ventī,",
          "nīl illīs vetitum est: incommendātaque tellūs",
          "omnis et omne fretum est, caelī quoque nūbila vexant",
          "excutiuntque ferīs rutilōs concursibus ignēs.",
          "quō magis hōs nōvī (nam nōvī et saepe paterna",
          "parvā domō vīdī), magis hoc reor esse timendōs.",
          "quod tua sī flectī precibus sententia nūllīs,",
          "cārē, potest, coniūnx, nimiumque es certus eundī,",
          "mē quoque tolle simul! certē iactābimur ūna,",
          "nec nisi quae patiar, metuam, pariterque ferēmus,",
          "quicquid erit, pariter super aequora lāta ferēmur.'",
          "Tālibus Aeolidis dictīs lacrimīsque movētur",
          "sīdereus coniūnx: neque enim minor ignis in ipsō est;",
