          "quā rūrsus vīsa velutī praesāga futūrī",
          "horruit Alcyonē lacrimāsque ēmīsit obortās",
          "amplexusque dedit trīstīque miserrima tandem",
          "ōre 'valē' dīxit conlāpsaque corpore tōtō est;",
