          "quippe sonant clāmōre virī, strīdōre rudentēs,",
          "undārum incursū gravis unda, tonitribus aether.",
          "flūctibus ērigitur caelumque aequāre vidētur",
          "pontus et inductās aspergine tangere nūbēs;",
          "et modo, cum fulvās ex īmō vertit harēnās,",
          "concōlor est illīs, Stygia modo nigrior unda,",
          "sternitur interdum spūmīsque sonantibus albet.",
          "ipsa quoque hīs agitur vicibus Trāchīnia puppis",
          "et nunc sublīmis velutī dē vertice montis",
          "dēspicere in vallēs īmumque Acheronta vidētur,",
          "nunc, ubi dēmissam curvum circumstetit aequor,",
          "suspicere īnfernō summum dē gurgite caelum.",
          "saepe dat ingentem flūctū lātus icta fragōrem",
          "nec levius pulsāta sonat, quam ferreus ōlim",
          "cum lacerās ariēs bālistave concutit arcēs,",
          "utque solent sūmptīs incursū vīribus īre",
          "pectore in arma ferī prōtentaque tēla leōnēs,",
          "sīc, ubi sē ventīs admīserat undā coortīs,",
          "ībat in alta ratīs multōque erat altior illīs;",
          "iamque labant cuneī, spoliātaque tegmine cērae",
          "rīma patet praebetque viam lētālibus undīs.",
          "ecce cadunt largī resolūtīs nūbibus imbrēs,",
          "inque fretum crēdās tōtum dēscendere caelum,",
          "inque plāgās caelī tumefactum ascendere pontum.",
          "vēla madent nimbīs, et cum caelestibus undīs",
          "aequoreae miscentur aquae; caret ignibus aether,",
          "caecaque nox premitur tenebrīs hiemīsque suīsque.",
          "discutiunt tamen hās praebentque micantia lūmen",
          "fulmina: fulmineīs ārdēscunt ignibus imbrēs.",
          "dat quoque iam saltus intrā cavā texta carīnae",
          "flūctūs; et ut mīles, numerō praestantior omnī,",
          "cum saepe adsiluit dēfēnsae moenibus urbis,",
          "spē potītur tandem laudisque accēnsus amōre",
          "inter mīlle virōs mūrum tamen occupat ūnus,",
          "sīc ubi pulsārunt noviēns latera ardua flūctūs,",
          "vastius īnsurgēns decimae ruit impetus undae",
          "nec prius absistit fessam oppugnāre carīnam,",
          "quam velut in captae dēscendat moenia nāvis.",
          "pars igitur temptābat adhūc invādere pīnum,",
          "pars maris intus erat: trepidant haud sētius omnēs,",
          "quam solet urbs aliīs mūrum fodientibus extrā",
          "atque aliīs mūrum trepidāre tenentibus intus.",
          "dēficit ars, animīque cadunt, totidemque videntur,",
          "quot veniunt flūctūs, ruere atque inrumpere mortēs.",
          "nōn tenet hīc lacrimās, stupet hic, vocat ille beātōs,",
          "fūnera quōs maneant, hīc vōtīs nūmen adōrat",
          "bracchiaque ad caelum, quod nōn videt, inrita tollēns",
          "poscit opem; subeunt illī frāterque parēnsque,",
          "huic cum pignoribus domūs et quodcunque relictum est;",
          "Alcyonē Ceyca movet, Ceycis in ōre",
          "nūlla nisi Alcyonē est et, cum dēsīderet ūnam,",
          "gaudet abesse tamen; patriae quoque vellet ad ōrās",
          "respicere inque domum suprēmōs vertere vultūs,",
          "vērum, ubi sit, nescit: tantā vertīgine pontus",
          "fervet, et inductā piceīs ē nūbibus umbra",
          "omne latet caelum, duplicātaque noctis imāgō est.",
          "frangitur incursū nimbōsī turbinis arbor,",
          "frangitur et regimen, spoliīsque animōsa superstes",
          "undā, velut victrīx, sinuātaque dēspicit undās;",
          "nec levius, quam sīquis Athōn Pindumve revulsōs",
          "sēde suā tōtōs in apertum ēverterit aequor,",
          "praecipitāta cadit pariterque et pondere et ictū",
          "mergit in īmā ratem; cum quā pars magna virōrum",
          "gurgite pressa gravī neque in āera reddita fātō",
          "fūnctā suō est, aliī partēs et membra carīnae",
          "trunca tenent: tenet ipse manū, qua scēptra solēbat,",
          "fragmina nāvigiī Ceyx socerumque patremque",
          "invocat heu! frūstrā, sed plūrima nantis in ōre",
          "Alcyonē coniūnx: illam meminitque refertque,",
          "illīus ante oculōs ut agant sua corpora flūctūs",
          "optat et exanimīs manibus tumulētur amīcīs.",
          "dum natat, absentem, quotiēns sinit hīscere flūctūs,",
          "nōminat Alcyonēn ipsīsque inmurmurat undīs.",
          "ecce super mediōs flūctūs niger arcus aquārum",
          "frangitur et rupta mersum caput obruit unda.",
          "Lūcifer obscūrus nec quem cognōscere possēs",
          "illā lūce fuit, quoniamque excēdere caelō",
          "nōn licuit, dēnsīs tēxit suā nūbibus ōrā.",
          "Aeolis intereā, tantōrum ignāra malōrum,",
          "dīnumerat noctēs et iam, quās induat ille,",
          "festīnat vestēs, iam quās, ubi vēnerit ille,",
          "ipsa gerat, reditusque sibi prōmittit inānēs.",
          "omnibus illa quidem superīs pia tūra ferēbat,",
          "ante tamen cūnctōs Iūnōnis templa colēbat",
          "prōque virō, quī nūllus erat, veniēbat ad ārās",
          "utque foret sospes coniūnx suus utque redīret,",
          "optābat, nūllamque sibi praeferret; at illī",
          "hoc dē tot vōtīs poterat contingere solum."
