          "Quō simul intrāvit manibusque obstantia virgō",
          "Somnia dimōvit, vestīs fulgōre relūxit",
          "sacra domus, tardaque deus gravitāte iacentēs",
          "vix oculōs tollēns iterumque iterumque relābēns",
          "summaque percutiēns nūtantī pectora mentō",
          "excussit tandem sibi sē cubitōque levātus,",
          "quid veniat, (cognōvit enim) scītātur, at illa:",
          "'Somne, quiēs rērum, placidissimē, Somne, deōrum,",
