          "fessa ministeriīs mulcēs reparāsque labōrī,",
          "Somnia, quae vērās aequent imitāmine fōrmās,",
          "Herculea Trachīne iubē sub imāgine rēgis",
          "Alcyonēn adeant simulācraque naufraga fingant.",
          "imperat hoc Iūnō.' postquam mandāta perēgit,",
          "Īris abit: neque enim ulterius tolerāre sopōrīs",
          "vim poterat, lābīque ut somnum sēnsit in artūs,",
          "effugit et remeat per quōs modo vēnerat arcus.",
          "At pater ē populō nātōrum mīlle suōrum",
          "excitat artificem simulātōremque figūrae",
