          "ōraque nostra tuum frūstrā clāmantia nōmen",
          "inplērunt flūctūs.—nōn haec tibi nūntiat auctor",
          "ambiguus, nōn ista vagīs rūmōribus audīs:",
          "ipse ego fāta tibi praesēns mea naufragus edō.",
          "surge, age, dā lacrimās lūgubriaque indue nec mē",
          "indēplōrātum sub inānia Tartara mitte!'",
