          "crēderet esse suī (flētus quoque fundere vērōs",
          "vīsūs erat), gestumque manus Ceycis habēbat.",
          "ingemit Alcyonē lacrimāns, mōtatque lacertōs",
          "per somnum corpusque petēns amplectitur aurās",
          "exclāmatque: 'manē! quō tē rapis? ībimus ūna.'",
          "vōce suā speciēque virī turbāta sopōrem",
          "excutit et prīmō, sī sit, circumspicit, illīc,",
          "quī modo vīsus erat; nam mōtī vōce ministrī",
          "intulerant lūmen. postquam nōn invēnit usquam,",
