          "vēra meī. nōn ille quidem, sī quaeris, habēbat",
          "adsuētōs vultūs nec quō prius, ōre nitēbat:",
          "pallentem nūdumque et adhūc ūmente capillō",
          "īnfēlīx vīdī. stetit hoc miserābilis ipsō",
          "ecce locō'; et quaerit, vestīgia sīquā supersint.",
          "'hoc erat, hoc, animō quod dīvīnante timēbam,",
          "et nē mē fugiēns ventōs sequerēre rogābam.",
          "at certē vellem, quoniam peritūrus abībās,",
