          "et tibi nunc saltem veniam comes, inque sepulcrō",
          "sī nōn urna, tamen iunget nōs littera: sī nōn",
          "ossibus ossa meīs, at nōmen nōmine tangam.'",
          "plūra dolor prohibet, verbōque intervenit omnī",
          "plangor, et attonitō gemitus ā corde trahuntur."
