        "paragraphs": [
          "Nescius adsūmptīs Priamus pater Aesacōn ālīs",
          "vīvere lūgēbat: tumulō quoque nōmen habentī",
          "īnferiās dederat cum frātribus Hector inānēs;",
          "dēfuit officiō Paridis praesentia trīstī,",
          "postmodo quī rapta longum cum coniuge bellum",
          "attulit in patriam: coniūrātaeque sequuntur",
          "mīlle ratēs gentīsque simul commūne Pelasgae;",
          "nec dīlātā foret vindicta, nisi aequora saevī",
          "invia fēcissent ventī, Boeōtaque tellūs",
          "Aulide piscōsā puppēs tenuisset itūrās.",
          "hīc patriō dē mōre Iovī cum sacra parāssent,",
          "ut vetus accēnsīs incanduit ignibus ārā,",
          "serpere caeruleum Danaī vidēre dracōnem",
          "in platanum, coeptīs quae stābat proxima sacrīs.",
          "nīdus erat volucrum bis quattuor arbore summā:",
          "quās simul et mātrem circum sua damna volantem",
          "corripuit serpēns avidōque recondidit ōre,",
          "obstipuēre omnēs, at vērī prōvidus augur",
          "Thestoridēs 'vincēmus'; ait, 'gaudēte, Pelasgī!",
          "Troia cadet, sed erit nostrī morā longā labōris,'",
          "atque novem volucrēs in bellī dīgerit annōs.",
          "ille, ut erat viridēs amplexūs in arbore rāmōs,",
          "fit lapis et signat serpentis imāgine saxum.",
          "Permanet Āoniīs Boreās violentus in undīs",
          "bellaque nōn trānsfert, et sunt, quī parcere Troiae",
          "Neptūnum crēdant, quia moenia fēcerat urbī;",
          "at nōn Thestoridēs: nec enim nescitve tacetve",
          "sanguine virgineō plācandam virginis īram",
          "esse deae. postquam pietātem pūblicā causā",
          "rēxque patrem vīcit, castumque datūrā cruōrem",
          "flentibus ante āram stetit Īphigenīa ministrīs,",
          "victa dea est nūbemque oculīs obiēcit et inter",
          "officium turbamque sacrī vōcēsque precantum",
          "supposita fertur mūtāsse Mycēnida cerva.",
          "ergō ubi, quā decuit, lēnīta est caede Diāna,",
          "et pariter Phoebēs, pariter maris īra recessit,",
          "accipiunt ventōs ā tergō mīlle carīnae",
          "multaque perpessae Phrygia potiuntur harēna.",
          "Orbē locus mediō est inter terrāsque fretumque",
          "caelestēsque plāgās, triplicīs cōnfīnia mundī;",
          "unde quod est usquam, quamvīs regiōnibus absit,",
          "īnspicitur, penetratque cavās vōx omnis ad aurēs:",
          "Fāma tenet summaque domum sibi legit in arce,",
          "innumerōsque aditūs ac mīlle forāmina tēctīs",
          "addidit et nūllīs inclūsit līmina portīs;",
          "nocte diēque patet: tōta est ex āere sonantī,",
          "tōta fremit vōcēsque refert iteratque quod audit;",
          "nūlla quiēs intus nūllaque silentia parte,",
          "nec tamen est clāmor, sed parvae murmura vōcis,",
          "quālia dē pelagī, sīquis procul audiat, undīs",
          "esse solent, quālemve sonum, cum Iuppiter ātrās",
          "increpuit nūbēs, extrēma tonitrua reddunt.",
          "ātria turba tenet: veniunt, leve vulgus, euntque",
          "mixtaque cum vērīs passim commenta vagantur",
          "milia rūmōrum cōnfūsaque verba volūtant;",
          "ē quibus hī vacuās inplent sermōnibus aurēs,",
          "hī nārrāta ferunt aliō, mēnsūrāque fictī",
          "crēscit, et audītis aliquid novus adicit auctor.",
          "illīc Crēdulitās, illīc temerārius Error",
          "vānaque Laetitia est cōnsternātīque Timōrēs",
          "Sēditiōque repēns dubiōque auctōre Susurrī;",
          "ipsa, quid in caelō rērum pelagōque gerātur",
          "et tellūre, videt tōtumque inquīrit in orbem."
        ],
