        "id": "metamorphoses-liber-xii-r3",
        "latinTitle": "VERSŪS 189–289",
        "title": "Verses 189–289",
        "hideHead": false,
        "paragraphs": [
          "'Clāra decōrē fuit prōlēs Elatēia Caenis,",
          "Thessalidum virgō pulcherrima, perque propinquās",
          "perque tuās urbēs (tibi enim populārīs, Achille),",
          "multōrum frūstrā vōtīs optāta procōrum.",
          "temptāsset Peleus thalamōs quoque forsitan illōs:",
          "sed iam aut contigerant illī cōnūbia mātris",
          "aut fuerant prōmissa tuae, nec Caenis in ūllōs",
          "dēnūpsit thalamōs sēcrētaque lītora carpēns",
          "aequoreī vim passa deī est (ita fāma ferēbat),",
          "utque novae Veneris Neptūnus gaudia cēpit,",
          "\"sint tua vōta licet\" dīxit \"sēcūra repulsae:",
          "ēlige, quid voveās!\" (eadem hoc quoque fāma ferēbat)",
          "\"magnum\" Caenis ait \"facit haec iniūriā vōtum,",
          "tāle patī iam posse nihil; dā, fēminā nē sim:",
          "omnia praestiterīs.\" graviōre novissima dīxit",
          "verba sonō poteratque virī vōx illa vidērī,",
          "sīcut erat; nam iam vōtō deus aequoris altī",
          "adnuerat dederatque super, nec saucius ūllīs",
          "vulneribus fierī ferrōve occumbere posset.",
          "mūnere laetus abit studiīsque virīlibus aevum",
          "exigit Atracidēs Pēnēiaque arva pererrat.",
          "'Dūxerat Hippodamen audācī Ixīone nātus",
          "nūbigenāsque ferōs positīs ex ōrdine mēnsīs",
          "arboribus tēctō discumbere iusserat antrō.",
          "Haemoniī procerēs aderant, aderāmus et ipsī,",
          "fēstaque cōnfūsa resonābat rēgia turbā.",
          "ecce canunt Hymenaeōn, et ignibus ātria fūmant,",
          "cīnctaque adest virgō mātrum nuruumque caterva,",
          "praesignis faciē; fēlīcem dīximus illā",
          "coniuge Pīrithoum, quod paene fefellimus ōmen.",
          "nam tibi, saevōrum saevissimē Centaurōrum,",
          "Euryte, quam vīnō pectus, tam virgine vīsa",
          "ārdet, et ēbrietās gemināta libīdine rēgnat.",
          "prōtinus ēversae turbant convīvia mēnsae,",
          "raptāturque cōmis per vim novā nūptā prehēnsīs.",
          "Eurytus Hippodamen, aliī, quam quisque probābant",
          "aut poterant, rapiunt, captaeque erat urbis imāgō.",
          "fēmineō clāmōre sonat domus: ōcius omnēs",
          "surgimus, et prīmus \"quae tē vēcordia,\" Thēseus",
          "\"Euryte, pulsat,\" ait, \"quī mē vīvente lacessās",
          "Pīrithoum violēsque duōs ignārus in ūnō?\"",
          "[nēve ea magnanimus frūstrā memorāverit ōre,",
          "submovet īnstantēs raptamque furentibus aufert.]",
          "ille nihil contrā, (neque enim dēfendere verbīs",
          "tālia facta potest) sed vindicis ōra protervīs",
          "īnsequitur manibus generōsaque pectora pulsat.",
          "forte fuit iuxtā signīs exstantibus asper",
          "antīquus crater; quem vastum vastior ipse",
          "sustulit Aegīdēs adversaque mīsit in ōrā:",
          "sanguinis ille globōs pariter cerebrumque merumque",
          "vulnere et ōre vomēns madidā resupīnus harēnā",
          "calcitrat. ārdēscunt germānī caede bimembrēs",
          "certātimque omnēs ūnō ōre \"arma, arma\" loquuntur.",
          "vīna dabant animōs, et prīma pōcula pugnā",
          "missa volant fragilēsque cadī curvīque lebētēs,",
          "rēs epulīs quondam, tum bellō et caedibus aptae.",
          "'Prīmus Ophīonidēs Amycus penetrālia dōnīs",
          "haut timuit spoliāre suīs et prīmus ab aede",
          "lampadibus dēnsum rapuit fūnāle coruscīs",
          "ēlātumque altē, velutī quī candida taurī",
          "rumpere sacrifica mōlītur colla secūrī,",
          "inlīsit frontī Lapithae Celadontis et ossa",
          "nōn cognōscendō cōnfūsa relinquit in ōre.",
          "exsiluēre oculī, disiectīsque ossibus ōris",
          "ācta retrō nāris mediōque est fīxa palātō.",
          "hunc pede convulsō mēnsae Pellaeus acernae",
          "strāvit humī Pelātēs dēiectō in pectora mentō",
          "cumque ātrō mixtōs spūtantem sanguine dentēs",
          "vulnere Tartareās geminātō mittit ad umbrās.",
          "'Proximus ut steterat spectāns altāria vultū",
          "fūmidā terribilī \"cūr nōn\" ait \"ūtimur istīs?\"",
          "cumque suīs Grȳnēus inmānem sustulit āram",
          "ignibus et medium Lapithārum iēcit in agmen",
          "dēpressitque duōs, Broteān et Ōrīōn: Orīō",
          "māter erat Mycalē, quam dēdūxisse canendō",
          "saepe reluctantī cōnstābat cornua lūnae.",
          "\"nōn impūne ferēs, tēlī modo cōpia dētur!\"",
          "dīxerat Exadius tēlīque habet īnstar, in alta",
          "quae fuerant pīnū vōtīvī cornua cervī.",
          "fīgitur hinc duplicī Grȳnēus in lūmina rāmō",
          "ēruiturque oculōs, quōrum pars cornibus haeret,",
          "pars fluit in barbam concrētāque sanguine pendet.",
          "'Ecce rapit mediīs flagrantem Rhoetus ab ārīs",
          "pruniceum torrem dextrāque ā parte Charaxī",
          "tempora perfringit fulvō prōtēcta capillō.",
          "correptī rapida, velutī seges ārida, flammā",
          "ārsērunt crīnēs, et vulnere sanguis inustus",
          "terribilem strīdōre sonum dedit, ut dare ferrum",
          "igne rubēns plērumque solet, quod forcipe curvā",
          "cum faber ēdūxit, lacubus dēmittit: at illud",
          "strīdet et in trepidā submersum sībilat undā.",
          "saucius hirsūtīs avidum dē crīnibus ignem",
          "excutit inque umerōs līmen tellūre revulsum",
          "tollit, onus plaustrī, quod nē permittat in hostem,",
          "ipsa facit gravitās: socium quoque saxea mōlēs",
          "oppressit spatiō stantem propiōre Comētēn.",
          "gaudia nec retinet Rhoetus: \"sīc, conprecor,\" inquit",
          "\"cētera sit fortīs castrōrum turba tuōrum!\"",
          "sēmicremōque novat repetītum stīpite vulnus",
          "terque quaterque gravī iūnctūrās verticis ictū",
          "rūpit, et in liquidō sēdērunt ossa cerebrō."
        ],
