          "cornua vāra boum multō rubefactā cruōre.",
          "'Huic ego (nam virīs animus dabat) \"aspice,\" dīxī",
          "\"quantum concēdant nostrō tua cornua ferrō\"",
          "et iaculum torsī: quod cum vītāre nequīret,",
          "opposuit dextram passūrae vulnera frontī:",
          "adfixa est cum fronte manūs; fit clāmor, at illum",
          "haerentem Peleus et acerbō vulnere vīctum",
          "(stābat enim propior) mediam ferit ēnse sub alvum.",
          "prōsiluit terraque ferōx sua vīscera trāxit",
          "tractaque calcāvit calcātaque rūpit et illīs",
          "crūra quoque inpediit et inānī concīdit alvō."
