          "īte procul, sī iūsta petō, tāctūque virīlēs",
          "virgineō removēte manūs! acceptior illī,",
          "quisquis is est, quem caede meā plācāre parātis,",
          "liber erit sanguis. sīquōs tamen ultima nostrī",
