          "vādit ad artificem dīrae, Polymestōra, caedis",
          "conloquiumque petit; nam sē mōnstrāre relictum",
          "velle latēns illī, quod nātō redderet, aurum.",
          "crēdidit Odrysius praedaeque adsuētus amōre",
