          "dē tantīs opibus praedam pius ēligit illam",
          "Ascaniumque suum profugaque per aequora classe",
          "fertur ab Antandrō scelerātaque līmina Thrācum",
          "et Polydōrēō mānantem sanguine terram",
          "linquit et ūtilibus ventīs aestūque secundō",
          "intrat Apollineam sociīs comitantibus urbem.",
          "hunc Anius, quō rēge hominēs, antistite Phoebus",
          "rīte colēbātur, templōque domōque recēpit",
          "urbemque ostendit dēlūbraque nōta duāsque",
          "Lātōna quondam stirpēs pariente retentās.",
          "tūre datō flammīs vīnōque in tūra profūsō",
          "caesārumque boum fibrīs dē mōre cremātīs",
          "rēgia tēcta petunt, positīque tapētibus altīs",
          "mūnera cum liquidō capiunt Cereālia Bacchō.",
          "tum pius Anchīsēs: 'ō Phoebī lēctē sacerdōs,",
          "fallor, an et nātum, cum prīmum haec moenia vīdī,",
          "bisque duās nātās, quantum reminīscor, habēbās?'",
          "huic Anius niveīs circumdata tempora vittīs",
          "concutiēns et trīstis ait: 'nōn falleris, hērōs",
          "maximē; vīdistī nātōrum quīnque parentem,",
          "quem nunc (tanta hominēs rērum incōnstantia versat)",
          "paene vidēs orbum. quod enim mihi fīlius absēns",
          "auxilium, quem dicta suō dē nōmine tellūs",
          "Andros habet prō patre locumque et rēgna tenentem?",
          "Dēlius augurium dēdit huic, dēdit altera Liber",
          "fēmineae stirpī vōtō maiōra fideque",
          "mūnera: nam tāctū nātārum cūncta meārum",
          "in segetem laticemque merī cānaeque Minervae",
          "trānsfōrmābantur, dīvesque erat ūsus in illīs.",
          "hoc ubi cognōvit Troiae populātor Atrīdēs,",
          "(nē nōn ex aliquā vestram sēnsisse procellam",
          "nōs quoque parte putēs), armōrum vīribus ūsus",
          "abstrahit invītās gremiō genitōris alantque",
          "imperat Argolicam caelestī mūnere classem.",
          "effugiunt, quō quaeque potest: Euboeā duābus",
          "et totidem natis Andros frāterna petīta est.",
          "mīles adest et, nī dēdantur, bella minātur:",
