          "iamque parābantur captīvīs vincla lacertīs:",
          "illae tollentēs etiamnum līberā caelō",
          "bracchia \"Bacche pater, fer opem!\" dīxēre, tulitque",
          "mūneris auctor opem, (sī mīrō perdere mōre",
          "ferre vocātur opem, nec quā ratiōne figūram",
          "perdiderint, potuī scīre aut nunc dīcere possum;",
          "summa mālī nota est: pennās sūmpsēre tuaeque",
          "coniugis in volucrēs, niveās abiēre columbās.'",
          "Tālibus atque aliīs postquam convīvia dictīs",
          "inplērunt, mēnsā somnum petiēre remōta",
          "cumque diē surgunt adeuntque ōrācula Phoebī,",
          "quī petere antīquam mātrem cognātaque iussit",
          "lītora; prōsequitur rēx et dat mūnus itūrīs,",
          "Anchīsae scēptrum, chlamydem pharetramque nepōtī,",
          "crātēra Aenēae, quem quondam trānstulit illī",
          "hospes ab Āoniīs Thersēs Ismēnius ōrīs:",
          "mīserat hunc illī Thersēs, fabricāverat Alcōn",
          "Hyleus et longō caelāverat argūmentō.",
          "urbs erat, et septem possēs ostendere portās:",
          "hae prō nōmine erant, et quae foret illa, docēbant;",
          "ante urbem exequiae tumulīque ignēsque rogīque",
          "effūsaeque comās et apertae pectora mātrēs",
          "significant lūctum; nymphae quoque flēre videntur",
          "siccātōsque querī fontēs: sine frondibus arbor",
          "nūda riget, rōdunt ārentia saxa capellae.",
          "ecce facit mediīs natās Ōrīōne Thēbīs",
          "hāc nōn fēmineum iugulō dare vulnus apertō,",
          "illāc dēmissō per fortia pectora tēlō",
          "prō populō cecidisse suō pulchrīsque per urbem",
          "fūneribus ferrī celebrīque in parte cremārī.",
          "tum dē virgineā geminōs exīre favīllā,",
          "nē genus intereat, iuvenēs, quōs fāma Corōnās",
          "nōminat, et cinerī māternō dūcere pompam.",
          "hāctenus antīquō signīs fulgentibus āere,",
          "summus inaurātō crater erat asper acanthō.",
          "nec leviōra datīs Troiānī dōna remittunt",
          "dantque sacerdōtī cūstōdem tūris acerram,",
          "dant pateram clāramque aurō gemmīsque corōnam.",
          "Inde recordātī Teucrōs ā sanguine Teucrī",
          "dūcere prīncipium Crēten tenuēre locīque",
