          "iūdicis, Actiacō quae nunc ab Apolline nota est,",
          "vōcālemque suā terram Dōdōnida quercū",
          "Chāoniōsque sinūs, ubi nātī rēge Molossō",
          "inpia subiectīs fugere incendia pennīs."
