          "Būthrōtos Phrygiō simulātāque Troiā tenētur;",
          "inde futūrōrum certī, quae cūncta fidēlī",
          "Prīamidēs Helenus monitū praedīxerat, intrant",
          "Sīcaniam: tribus haec excurrit in aequora linguīs,",
          "ē quibus imbriferōs est versa Pachȳnōs ad austrōs,",
          "mollibus oppositum zephyrīs Lilybaeōn, ad arctōs",
          "aequoris expertēs spectat boreānque Pelōrōs.",
          "hāc subeunt Teucrī, et rēmīs aestūque secundō",
          "sub noctem potītur Zanclaeā classis harēnā:",
          "Scylla latus dextrum, laevum inrequiēta Charybdis",
