          "ad pelagī nymphās, pelagī grātissima nymphīs,",
          "ībat et ēlūsōs iuvenum nārrābat amōrēs.",
          "cui dum pectendōs praebet Galatēa capillōs,",
          "tālibus adloquitur repetēns suspīria dictīs:",
