          "at mihi, cui pater est Nēreus, quam caerula Dōris",
          "ēnīxa est, quae sum turbā quoque tūta sorōrum,",
          "nōn nisi per lūctūs licuit Cyclōpīs amōrem",
          "effugere.' et lacrimae vōcem inpediēre loquentīs.",
          "quās ubi marmoreō dētersit pollice virgō",
          "et sōlāta deam est, 'refer, ō cārissima' dīxit",
