          "Ācidis in nōbīs fuerit praesentior, ēdam:",
          "pār utrumque fuit. prō, quanta potentia rēgnī",
          "est, Venus alma, tuī! nempe ille inmītīs et ipsīs",
          "horrendus silvīs et vīsus ab hospite nūllō",
          "inpūne et magnī cum dīs contemptor Olympī,",
          "quid sit amor, sentit validāque cupīdine captus",
          "ūritur oblītus pecorum antrōrumque suōrum.",
