          "lānigerae pecudēs nūllō dūcente secūtae.",
          "cui postquam pīnus, baculī quae praebuit ūsum,",
          "ante pedēs posita est antemnīs aptā ferendīs",
          "sūmptāque harundinibus conpācta est fistula centum,",
