          "Ācidis in gremiō residēns procul auribus hausī",
          "tālia dicta meīs audītaque mente notāvī:",
          "'\"Candidior foliō niveī Galatēa ligustrī,",
          "flōridior prātīs, longā prōcērior alnō,",
          "splendidior vitrō, tenerō lascīvior haedō,",
          "levior adsiduō dētrītīs aequore conchīs,",
