          "intrat et, ut manēs adeat per Averna paternōs,",
          "ōrat. at illa diū vultum tellūre morātum",
          "ērēxit tandemque deō furibunda receptō",
          "'magna petis,' dīxit, 'vir factīs maximē, cuius",
          "dexterā per ferrum, pietās spectāta per ignēs.",
          "pōne tamen, Troiāne, metum: potiere petītīs",
          "Ēlysiāsque domōs et rēgna novissima mundī",
          "mē duce cognōscēs simulācraque cāra parentīs.",
