          "Aeolōn ille refert Tuscō rēgnāre profundō,",
          "Aeolōn Hippotadēn, cohibentem carcere ventōs;",
          "quōs bovis inclūsōs tergō, memorābile mūnus,",
          "Dūlichium sūmpsisse ducem flātūque secundō",
          "lūcibus īsse novem et terram aspexisse petītam;",
          "proxima post nōnam cum sēsē aurōra movēret,",
          "invidia sociōs praedaeque cupīdine vīctōs",
          "esse; ratōs aurum, dēmpsisse ligāmina ventīs;",
          "cum quibus īsse retrō, per quās modo vēnerat undās,",
          "Aeoliīque ratem portūs repetīsse tyrannī.",
          "'inde Lamī veterem Laestrȳgonis' inquit 'in urbem",
          "vēnimus: Antiphatēs terra rēgnābat in illā.",
          "missus ad hunc ego sum, numerō comitante duōrum,",
          "vixque fuga quaesīta salūs comitīque mihique,",
          "tertius ē nōbīs Laestrȳgonis inpia tīnxit",
          "ōra cruōre suō. fugientibus īnstat et agmen",
          "concitat Antiphatēs; coeunt et saxa trabēsque",
          "coniciunt merguntque virōs merguntque carīnās.",
          "ūna tamen, quae nōs ipsumque vehēbat Ulixem,",
          "effūgit. āmissā sociōrum parte dolentēs",
          "multaque conquestī terrīs adlābimur illīs,",
          "quās procul hinc cernis (procul est, mihi crēde, videndā",
          "īnsulā vīsa mihi!) tūque ō iūstissimē Trōum,",
          "nātē dea, (neque enim fīnītō Mārte vocandus",
          "hostis es, Aenēa) moneō, fuge lītora Circēs!",
          "nōs quoque Circaeō religāta in lītore pīnū,",
          "Antiphatae memorēs inmānsuētīque Cyclōpīs,",
          "īre negābāmus; sed tēcta ignōta subīre",
          "sorte sumus lectī: sors mē fīdumque Polītēn",
          "Eurylochumque simul nimiīque Elpenora vīnī",
          "bisque novem sociōs Circaeā ad moenia mīsit.",
          "quae simul attigimus stetimusque in līmine tēctī,",
          "mīlle lupī mixtaeque lupīs ursaeque leaeque",
          "occursū fēcēre metum, sed nūlla timenda",
          "nūllaque erat nostrō factūrā in corpore vulnus;",
          "quīn etiam blandās movēre per āera caudās",
          "nostraque adūlantēs comitant vestīgia, dōnec",
          "excipiunt famulae perque ātria marmore tēcta",
          "ad dominam dūcunt: pulchrō sedet illā recessū",
          "sollemnī soliō pallamque indūta nitentem",
          "īnsuper aurātō circumvēlātur amictū.",
          "Nēreidēs nymphaeque simul, quae vellera mōtīs",
          "nūlla trahunt digitīs nec fīla sequentia dūcunt:",
          "grāmina dispōnunt sparsōsque sine ōrdine flōrēs",
          "sēcernunt calathīs variāsque colōribus herbās;",
          "ipsa, quod hae faciunt, opus exigit, ipsa, quis ūsus",
          "quōve sit in foliō, quae sit concordiā mixtīs,",
          "nōvit et advertēns pēnsās exāminat herbās.",
          "haec ubi nōs vīdit, dicta acceptāque salūte",
          "diffūdit vultūs et reddidit ōmina vōtīs.",
          "nec mora, miscērī tostī iubet hordea grānī",
          "mellaque vimque merī cum lacte coāgulā passō,",
          "quīque sub hāc lateant fūrtim dulcēdine, sūcōs",
          "adicit. accipimus sacra data pōcula dextra.",
          "quae simul ārentī sitientēs hausimus ōre,",
          "et tetigit summōs virgā dea dīra capillōs,",
          "(et pudet et referam) saetīs horrēscere coepī,",
          "nec iam posse loquī, prō verbīs edere raucum",
          "murmur et in terram tōtō prōcumbere vultū,",
          "osque meum sēnsī pandō occallēscere rōstrō,",
          "colla tumēre torīs, et quā modo pōcula parte",
          "sūmpta mihi fuerant, illa vestīgia fēcī",
          "cumque eadem passīs (tantum medicāmina possunt!)",
          "claudor hara, sōlumque suīs caruisse figūrā",
          "vīdimus Eurylochum: sōlus data pōcula fugit;",
          "quae nisi vītāsset, pecoris pars ūna manērem",
          "nunc quoque saetigērī, nec tantae clādis ab illō",
          "certior ad Circēn ultor vēnisset Ulixēs.",
          "pacifer huic dederat flōrem Cyllēnius album:",
          "moly vocant superī, nigrā rādīce tenētur;",
          "tūtus eō monitīsque simul caelestibus intrat",
          "ille domum Circēs et ad īnsidiōsa vocātus",
          "pōcula cōnantem virgā mulcēre capillōs",
          "reppulit et strictō pavidam dēterruit ēnse.",
          "inde fidēs dextraeque datae thalamōque receptus",
          "coniugiī dōtem sociōrum corpora poscit.",
          "spargimur ignōtae sūcīs meliōribus herbae",
          "percutimurque caput conversae verbere virgae,",
          "verbaque dīcuntur dictīs contrāria verbīs.",
          "quō magis illa canit, magis hoc tellūre lēvātī",
          "ērigimur, saetaeque cadunt, bifidōsque relinquit",
          "rīma pedēs, redeunt umerī et subiecta lacertīs",
          "bracchia sunt: flentem flentēs amplectimur ipsī",
          "haerēmusque ducīs collō nec verba locūtī",
          "ūlla priōra sumus quam nōs testantia grātōs.",
          "annua nōs illīc tenuit mora, multaque praesēns",
          "tempore tam longō vīdī, multa auribus hausī,",
          "hoc quoque cum multīs, quod clam mihi rettulit ūna",
          "quattuor ē famulīs ad tālia sacra parātis.",
          "cum duce namque meō Circē dum sōla morātur,",
          "illa mihi niveō factum dē marmore signum",
          "ostendit iuvenāle gerēns in vertice pīcum,",
          "aede sacrā positum multīsque īnsigne corōnīs.",
          "quis foret et quārē sacra colerētur in aede,",
          "cūr hanc ferret avem, quaerentī et scīre volentī",
          "\"accipe\" ait, \"Macareu, dominaeque potentia quae sit",
          "hinc quoque disce meae; tū dictīs adice mentem!"
