          "et genus omne avium mediīs ē partibus ōvī,",
          "nī scīret fierī, fierī quis posse putāret?",
          "sunt quī, cum clausō putrefacta est spīna sepulcrō,",
          "mūtārī crēdant hūmānās angue medullās.",
          "'Haec tamen ex aliīs generis prīmōrdia dūcunt,",
          "ūna est, quae reparet sēque ipsa resēminet, alēs:",
          "Assyriī phoenīcā vocant; nōn frūge neque herbīs,",
          "sed tūris lacrimīs et sūcō vīvit amōmī.",
          "haec ubi quīnque suae conplēvit saecula vītae,",
          "īlicet in rāmīs tremulaeque cacūmine palmae",
          "unguibus et pūrō nīdum sibi cōnstruit ōre,",
          "quō simul ac casiās et nardī lēnīs aristās",
          "quassaque cum fulvā substrāvit cinnama murrā,",
          "sē super inpōnit fīnitque in odōribus aevum.",
          "inde ferunt, totidem quī vīvere dēbeat annōs,",
          "corpore dē patriō parvum phoenīcā renāscī;",
          "cum dedit huic aetās vīrēs, onerīque ferendō est,",
          "ponderibus nīdī rāmōs levat arboris altae",
          "fertque pius cūnāsque suās patriumque sepulcrum",
          "perque levēs aurās Hyperīonis urbe potītus",
          "ante forēs sacrās Hyperīonis aede repōnit."
