        "paragraphs": [
          "'Sī tamen est aliquid mīrae novitātis in istīs,",
          "alternāre vicēs et, quae modo fēmina tergō",
          "passa marem est, nunc esse marem mīrēmur hyaenam;",
          "id quoque, quod ventīs animal nūtrītur et aura,",
          "prōtinus adsimulat, tetigit quōscumque colōrēs.",
          "victa racēmiferō lyncās dēdit Indiā Bacchō:",
          "ē quibus, ut memorant, quicquid vēsīca remīsit,",
          "vertitur in lapidēs et congelat aere tāctō.",
          "sīc et curalium quō prīmum contigit aurās",
          "tempore, dūrēscit: mollis fuit herba sub undīs.",
          "'Dēsinet ante diēs et in altō Phoebus anhēlōs",
          "aequore tinguet equōs, quam cōnsequar omnia verbīs",
          "in speciēs trānslāta novās: sīc tempora vertī",
          "cernimus atque illās adsūmere rōbora gentēs,",
          "concīdere hās; sīc magnā fuit cēnsūque virīsque",
          "perque decem potuit tantum dare sanguinis annōs,",
          "nunc humilis veterēs tantummodo Troiā ruīnās",
          "et prō dīvitiīs tumulōs ostendit avōrum.",
          "clāra fuit Spartē, magnae viguēre Mycēnae,",
          "nec nōn et Cēcropis, nec nōn Amphīonis arcēs.",
          "vīle sōlum Spartē est, altae cecidēre Mycēnae,",
          "Oedipodīoniae quid sunt, nisi nōmina, Thēbae?",
          "quid Pandīoniae restant, nisi nōmen, Athēnae?",
          "nunc quoque Dardaniam fāma est cōnsurgere Rōmam,",
          "Appenninigenae quae proxima Thybridīs undīs",
          "mōle sub ingentī rērum fundāmina pōnit:",
          "haec igitur fōrmam crēscendō mūtat et ōlim",
          "inmēnsī caput orbis erit! sīc dīcere vātēs",
          "fāticināsque ferunt sortēs, quantumque recordor,",
          "Prīamidēs Helenus flentī dubiōque salūtis",
          "dīxerat Aenēae, cum rēs Troiāna labāret:",
          "\"nātē dea, sī nōta satis praesāgia nostrae",
          "mentis habēs, nōn tōta cadet tē sospite Troiā!",
          "flamma tibi ferrumque dabunt iter: ībis et ūna",
          "Pergama rapta ferēs, dōnec Troiaeque tibique",
          "externum patria contingat amīcius arvum,",
          "urbem et iam cernō Phrygiōs dēbēre nepōtēs,",
          "quanta nec est nec erit nec vīsa priōribus annīs.",
          "hanc aliī procerēs per saecula longa potentem,",
          "sed dominam rērum dē sanguine nātūs Iūlī",
          "efficiet, quō cum tellūs erit ūsa, fruentur",
          "aetheriae sēdēs, caelumque erit exitus illī.\"",
          "haec Helenum cecinisse penātigerō Aenēae",
          "mente memor referō cognātaque moenia laetor",
          "crēscere et ūtiliter Phrygibus vīcisse Pelasgōs.",
          "'Nē tamen oblītīs ad mētam tendere longē",
          "exspatiēmur equīs, caelum et quodcumque sub illō est,",
          "inmūtat fōrmās, tellūsque et quicquid in illā est.",
          "nōs quoque, pars mundī, quoniam nōn corpora sōlum,",
          "vērum etiam volucrēs animae sumus, inque ferīnās",
          "possumus īre domōs pecudumque in pectora condī,",
          "corpora, quae possint animās habuisse parentum",
          "aut frātrum aut aliquō iūnctōrum foedere nōbīs",
          "aut hominum certē, tūta esse et honesta sināmus",
          "nēve Thyestēīs cumulēmus vīscera mēnsīs!",
          "quam male cōnsuēscit, quem sē parat ille cruōrī",
          "inpius hūmānō, vitulī quī guttura ferrō",
          "rumpit et inmōtās praebet mūgītibus aurēs,",
          "aut quī vāgītūs similēs puerīlibus haedum",
          "ēdentem iugulāre potest aut alitē vēscī,",
          "cui dēdit ipse cibōs! quantum est, quod dēsit in istīs",
          "ad plēnum facinus? quō trānsitus inde parātur?",
          "bōs āret aut mortem seniōribus inpūtet annīs,",
          "horriferum contrā boreān ovis arma ministret,",
          "ūbera dent saturae manibus pressanda capellae!",
          "rētia cum pedicīs laqueōsque artēsque dolōsās",
          "tollite! nec volucrem viscātā fallite virgā",
          "nec formīdātīs cervōs inclūdite pinnīs",
          "nec cēlāte cibīs uncōs fallācibus hāmōs;",
          "perditē sīquā nocent, vērum haec quoque perditē tantum:",
          "ōra cruōre vacent alimentaque mītia carpant!'",
          "Tālibus atque aliīs īnstrūctō pectore dictīs",
          "in patriam remeāsse ferunt ultrōque petītum",
          "accēpisse Numam populī Latiālīs habēnās.",
          "coniuge quī fēlīx nymphā ducibusque Camēnīs",
          "sacrificōs docuit rītūs gentemque ferōcī",
          "adsuētam bellō pācis trādūxit ad artēs.",
          "quī postquam senior rēgnumque aevumque perēgit,",
          "exstīnctum Latiaeque nurūs populusque patrēsque",
          "dēflēvēre Numam; nam coniūnx urbe relicta",
          "vallis Arīcīnae dēnsīs latet abdita silvīs",
          "sacraque Orestēae gemitū questūque Diānae",
          "inpedit. ā! quotiēns nymphae nemorisque lacusque,",
          "nē faceret, monuēre et cōnsōlantia verba",
          "dīxērunt! quotiēns flentī Thēsēius hērōs",
          "'siste modum,' dīxit 'neque enim fortūna querenda",
          "sōla tua est; similēs aliōrum respice cāsūs:",
          "mītius ista ferēs, utinamque exempla dolentem",
          "nōn mea tē possent relevāre! sed et mea possunt."
        ],
