        "latinTitle": "VERSŪS 624–746",
        "title": "Verses 624–746",
        "hideHead": false,
        "paragraphs": [
          "Pandite nunc, Mūsae, praesentia nūmina vātum,",
          "(scītis enim, nec vōs fallit spatiōsa vetustās,)",
          "unde Corōnīdēn circumflua Thybridis altī",
          "īnsulā Rōmuleae sacrīs adiēcerit urbis.",
          "Dīra luēs quondam Latiās vitiāverat aurās,",
          "pallidaque exsanguī squālēbant corpora morbō.",
          "fūneribus fessī postquam mortālia cernunt",
          "temptāmenta nihil, nihil artēs posse medentum,",
          "auxilium caeleste petunt mediamque tenentēs",
          "orbis humum Delphōs adeunt, ōrācula Phoebī,",
          "utque salūtifera miserīs succurrēre rēbus",
          "sorte velit tantaeque urbis mala fīniat, ōrant:",
          "et locus et laurus et, quās habet ipse, pharetrae",
          "intremuēre simul, cortīnāque reddidit īmō",
          "hanc adytō vōcem pavefactaque pectora mōvit",
          "'quod petis hinc, propiōre locō, Rōmāne, petīssēs,",
          "et pete nunc propiōre locō: nec Apolline vōbīs,",
          "quī minuat lūctus, opus est, sed Apolline nātō.",
          "īte bonīs avibus prōlemque accersītē nostram.'",
          "iussa deī prūdēns postquam accēpēre senātus,",
          "quam cōlat, explōrant, iuvenis Phoebēius urbem,",
          "quīque petant ventīs Epidauria lītora, mittunt;",
          "quae simul incurvā missī tetigēre carīnā,",
          "concilium Grāiōsque patrēs adiēre, darentque,",
          "ōrāvēre, deum, quī praesēns fūnera gentis",
          "fīniat Ausoniae: certās ita dīcere sortēs.",
          "dissīdet et variat sententia, parsque negandum",
          "nōn putat auxilium, multī retinēre suamque",
          "nōn ēmittere opem nec nūmina trādere suādent:",
          "dum dubitant, sēram pepulēre crepuscula lūcem;",
          "umbraque tellūris tenebrās indūxerat orbī,",
          "cum deus in somnīs opifer cōnsistere vīsus",
          "ante tuum, Rōmāne, torum, sed quālis in aede",
          "esse solet, baculumque tenēns agreste sinistrā",
          "caesariem longae dextrā dēdūcere barbae",
          "et placidō tālēs ēmittere pectore vōcēs:",
          "'pōne metus! veniam simulācraque nostra relinquam.",
          "hunc modo serpentem, baculum quī nexibus ambit,",
          "perspice et usque nōta vīsū, ut cognōscere possīs!",
          "vertar in hunc: sed maior erō tantusque vidēbor,",
          "in quantum vertī caelestia corpora dēbent.'",
          "extemplō cum vōce deus, cum vōce deōque",
          "somnus abit, somnīque fugam lūx alma secūta est.",
          "posterā sīdereōs aurōra fugāverat ignēs:",
          "incertī, quid agant, procerēs ad templa petītī",
          "conveniunt operōsa deī, quāque ipse morārī",
          "sēde velit, signīs caelestibus indicet, ōrant.",
          "vix bene dēsierant, cum cristīs aureus altīs",
          "in serpente deus praenūntia sībila mīsit",
          "adventūque suō signumque ārāsque forēsque",
          "marmoreumque solum fastīgiaque aurea mōvit",
          "pectoribusque tenus mediā sublīmis in aede",
          "cōnstitit atque oculōs circumtulit igne micantēs:",
          "territa turba pavet, cognōvit nūmina castōs",
          "ēvīnctus vittā crīnēs albente sacerdōs",
          "et 'deus ēn, deus est! animīs linguīsque favēte,",
          "quisquis ades!' dīxit 'sīs, ō pulcherrime, vīsus",
          "ūtiliter populōsque iuvēs tua sacra colentēs!'",
          "quisquis adest, iussum venerātur nūmen, et omnēs",
          "verba sacerdōtis referunt gemināta piumque",
          "Aeneadae praestant et mente et vōce favōrem.",
          "adnuit hīs mōtīsque deus ratā pignora cristīs",
          "ter repetīta dēdit vibrāta sībilā linguā;",
          "tum gradibus nitidīs dēlābitur ōraque retrō",
          "flectit et antīquās abitūrus respicit ārās",
          "adsuētāsque domōs habitātaque templa salūtat.",
          "inde per iniectīs adopertam flōribus ingēns",
          "serpit humum flectitque sinūs mediamque per urbem",
          "tendit ad incurvō mūnītōs aggere portus.",
          "restitit hīc agmenque suum turbaeque sequentis",
          "officium placidō vīsus dīmittere vultū",
          "corpus in Ausoniā posuit rate: nūminis illa",
          "sēnsit onus, pressā estque deī gravitāte carīnā;",
          "Aeneadae gaudent caesōque in lītore taurō",
          "tortā corōnātae solvunt retinācula nāvis.",
          "inpulerat levis aura ratem: deus ēminet altē",
          "inpositāque premēns puppim cervīce recurvam",
          "caeruleās dēspectat aquās modicīsque per aequor",
          "Īōnium zephyrīs sextae Pallantidos ortū",
          "Ītaliam tenuit praeterque Lacīniā templō",
          "nōbilitāte deae Scylacēaque lītora fertur;",
          "linquit Iāpygiam laevīsque Amphrīsia rēmīs",
          "saxa fugit, dextrā praerupta Cocinthia parte,",
          "Romethiumque lēgit Caulōnaque Nāryciamque",
          "ēvincitque fretum Siculīque angusta Pelōrī",
          "Hippotadaeque domōs rēgis Temesēsque metalla",
          "Leucosiamque petit tepidīque rosāria Paestī.",
          "inde legit Capreās prōmunturiumque Minervae",
          "et Surrentīnō generōsōs palmite collēs",
          "Herculeamque urbem Stabiāsque et in ōtiā nātam",
          "Parthenopēn et ab hāc Cūmaeae templa Sibyllae.",
          "hinc calidī fontēs lentisciferumque tenētur",
          "Līternum multamque trahēns sub gurgite harēnam",
          "Volturnus niveīsque frequēns Sinuessa columbīs",
          "Minturnaeque gravēs et quam tumulāvit alumnus",
          "Antiphataeque domūs Trāchāsque obsessa palūde",
          "et tellūs Circaeā et spissī lītoris Antium.",
          "hūc ubi vēliferam nautae advertere carīnam,",
          "(asper enim iam pontus erat), deus explicat orbēs",
          "perque sinūs crēbrōs et magnā volūmina lābēns",
          "templa parentis init flāvum tangentia lītus.",
          "aequore plācātō patriās Epidaurius ārās",
          "linquit et hospitiō iūnctī sibi nūminis ūsus",
          "lītoream tractū squāmae crepitantis harēnam",
          "sulcat et innīxus moderāmine nāvis in altā",
          "puppe caput posuit, dōnec Castrumque sacrāsque",
          "Lāvīnī sēdēs Tiberīnaque ad ōstia venit.",
          "hūc omnis populī passim mātrumque patrumque",
          "obvia turba ruit, quaeque ignēs, Trōica, servant,",
          "Vesta, tuōs, laetōque deum clāmōre salūtant.",
          "quāque per adversās nāvis cita dūcitur undās,",
          "tūra super rīpās ārīs ex ōrdine factīs",
          "parte ab utrāque sonant et odōrant āera fūmīs,",
          "ictaque coniectōs incalfacit hostiā cultrōs.",
          "iamque caput rērum, Rōmānam intrāverat urbem:",
          "ērigitur serpēns summōque acclīnia malō",
          "colla movet sēdēsque sibi circumspicit aptās.",
          "scinditur in geminās partēs circumfluus amnis",
          "(Īnsula nōmen habet) laterumque ā parte duōrum",
          "porrigit aequālēs mediā tellūre lacertōs:",
          "hūc sē dē Latiā pīnū Phoebēius anguis",
          "contulit et fīnem speciē caeleste resūmptā",
          "lūctibus inposuit vēnitque salūtifer urbī."
        ],
