          "Iamque opus exēgī, quod nec Iovis īra nec ignis",
          "nec poterit ferrum nec edāx abolēre vetustās.",
          "cum volet, illa diēs, quae nīl nisi corporis huius",
          "iūs habet, incertī spatium mihi fīniat aevī:",
          "parte tamen meliōre meī super alta perennīs",
          "astra ferar, nōmenque erit indēlēbile nostrum,",
          "quāque patet domitīs Rōmāna potentia terrīs,",
          "ōre legar populī, perque omnia saecula fāma,",
          "sīquid habent vērī vātum praesāgia, vīvam."
